package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IdTokenEncryptedResponseEncVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property id token encrypted response enc of trusted client ")
  void test_id_token_encrypted_response_enc_v_o_builder() {
    Assertions.assertFalse(
        IdTokenEncryptedResponseEncVO.nullValue().getIdTokenEncryptedResponseEnc().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        IdTokenEncryptedResponseEncVO.tryFrom(null).getIdTokenEncryptedResponseEnc().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        IdTokenEncryptedResponseEncVO.from("one").getIdTokenEncryptedResponseEnc().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> IdTokenEncryptedResponseEncVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]",
        IdTokenEncryptedResponseEncVO.from("one").toString());
  }
}
